// TH16 v1.00a Extra, st07.ecl.txt MainSub04 1258-1273.
// Dependencies: GirlA03 265-274, GirlA03_at 276-292, GirlA03_at2 294-313.
// Source has no difficulty mask; this card implements the Extra behavior (rank 4) only.

const TH16_RICE: int = 480;      // source etSprite type 8; source color 6 kept
const RICE_COLOR: int = 6;

const OPENING_BUFFER: int = 120;
const TIME_LIMIT: int = 2100;

const SPAWN_ROUNDS: int = 30;    // MainSub04 $A = 30; check-first loop runs 30 bodies
const FIRE_BURSTS: int = 1000;   // GirlA03_at2 $A = 1000

// GirlA03_at2: one 4-way ring (etAim 3, etCount 4x1) every 3 frames.
// The mode-3 ring is symmetric under the child mirror, so both sides use the
// literal etAngle expression (random rotation sign is the only difference).
async sub girl_fire() {
    wait(10);
    var n: int = 0;
    while n < FIRE_BURSTS {
        // etAngle base = pi/2 + %RANDF * 5deg, sampled once per burst.
        var r: int = rand(65536);
        var u: fx = ((r - 32768) as fx / 65536) + 0.5fx;
        var off: int = (910fx * u) as int;
        var base: int = 16384 + off;
        for i in 0..4 {
            var a: angle = (base + i * 16384) as angle;
            // etEx type 2 (ANIM) a=1: spawn position -= 4 * velocity.
            _ = fire(TH16_RICE, RICE_COLOR,
                     $self_x - 4fx * cos(a), $self_y - 4fx * sin(a),
                     1fx, a, none, none);
        }
        n = n + 1;
        wait(3);
    }
}

// GirlA03 / GirlA03_at: boxes, movement and the firing async.
// f0 is the inherited MainSub04 %F0 snapshot (no in-scope reader).
async sub girl(side: int, f0: fx) {
    set_self_fx(0, f0);
    set_invuln(65535);
    set_hurtbox(12fx);            // setHurtbox(24,24) -> r 12
    set_hitbox(8fx);              // setHitbox(16,16) -> r 8
    spawn girl_fire();

    var a1: int = 4096;           // 22.5 deg, moveVel(0.3926991, 3.2)
    var a2: int = 16384;          // 90 deg, moveVelTime(120, mode1, ...)
    var a3: int = 28672;          // 157.5 deg, moveVelTime(60, mode4, ...)
    if side != 0 {
        // enmCreateM: mirror x/angle at each movement write point.
        a1 = 32768 - a1;
        a2 = 32768 - a2;
        a3 = 32768 - a3;
    }
    move_vel(0, a1 as angle, 3.2fx, EASE_LINEAR);
    move_vel(120, a2 as angle, 2.0fx, EASE_QUAD_IN);
    wait(120);
    move_vel(60, a3 as angle, 4.0fx, EASE_QUAD_OUT);
    loop { wait(1000); }
}

// MainSub04: 30 rounds of (GirlA03 left, wait 20, GirlA03 mirrored right, wait 20).
async sub pattern() {
    wait(OPENING_BUFFER);
    var f0: fx = 1.6fx;
    for k in 0..SPAWN_ROUNDS {
        var rl: int = rand(65536);
        var xl: fx = -150fx + (((rl - 32768) as fx / 32768) * 64fx);
        _ = spawn_enemy(xl, -16fx, 50, 0, 1000, 0, girl(0, f0));
        wait(20);
        var rr: int = rand(65536);
        var xr: fx = 150fx + (((rr - 32768) as fx / 32768) * 64fx);
        _ = spawn_enemy(xr, -16fx, 50, 0, 1000, 0, girl(1, f0));
        wait(20);
        f0 = f0 + 0.013fx;
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
